var builder = WebApplication.CreateBuilder(args);

// Add services to the container.

var app = builder.Build();

// Configure the HTTP request pipeline.

app.UseHttpsRedirection();

var summaries = new[]
{
    "Freezing", "Bracing", "Chilly", "Cool", "Mild", "Warm", "Balmy", "Hot", "Sweltering", "Scorching"
};

app.MapGet("/weatherforecast", () =>
{
    var forecast =  Enumerable.Range(1, 5).Select(index =>
        new WeatherForecast
        (
            DateOnly.FromDateTime(DateTime.Now.AddDays(index)),
            Random.Shared.Next(-20, 55),
            summaries[Random.Shared.Next(summaries.Length)]
        ))
        .ToArray();
    return forecast;
});

app.Run();

record WeatherForecast(DateOnly Date, int TemperatureC, string? Summary)
{
    public int TemperatureF => 32 + (int)(TemperatureC / 0.5556);
}

arguments.new_str:
using System.Text.Json.Serialization;
using Microsoft.AspNetCore.Http.HttpResults;
using ProductsApi.Models;
using ProductsApi.Services;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<IProductService, InMemoryProductService>();

builder.Services.ConfigureHttpJsonOptions(options =>
{
    options.SerializerOptions.Converters.Add(new JsonStringEnumConverter());
});

builder.Services.AddOpenApi();

var app = builder.Build();

app.MapOpenApi();

app.UseHttpsRedirection();

var products = app.MapGroup("/api/products")
    .WithTags("Products");

products.MapGet("/", (IProductService service) => service.GetAll())
    .WithSummary("List all products")
    .WithDescription("Returns every product currently stored in the catalog.");

products.MapGet("/{id:int}", Results<Ok<Product>, NotFound> (int id, IProductService service) =>
    {
        var product = service.GetById(id);
        return product is not null
            ? TypedResults.Ok(product)
            : TypedResults.NotFound();
    })
    .WithSummary("Get a product by ID")
    .WithDescription("Returns a single product matching the given identifier, or 404 if not found.");

products.MapPost("/", Created<Product> (CreateProductRequest request, IProductService service) =>
    {
        var product = service.Create(request);
        return TypedResults.Created($"/api/products/{product.Id}", product);
    })
    .WithSummary("Create a new product")
    .WithDescription("Adds a new product to the catalog and returns it with the assigned ID and timestamp.");

app.Run();

